logger = logging.getLogger("aichat_sdk")

MCP_TOOL_TIMEOUT_SECONDS = 10

DEFAULT_TOOLS_SERVER = "aichat-tools"

_tool_loop: asyncio.AbstractEventLoop | None = None


def _get_tool_loop() -> asyncio.AbstractEventLoop:
    """懒启动一个常驻线程的事件循环，所有工具调用（含外部 server 的长连接）都在这个 loop 上执行。

    fastmcp 会把同步（def）工具直接跑在所在事件循环里，工具卡住时整个 loop
    被冻结，asyncio 层面的超时永远不会触发，所以工具不能跑在主循环上；
    又因为多个线程并发连接同一个 in-memory FastMCP server 会互相卡死，
    只能用单个常驻 loop，而不是每次调用新开线程。外部 stdio server 的
    Client 绑定创建它的 loop，所以也统一放在这里创建和使用。
    """
    global _tool_loop
    if _tool_loop is None:
        _tool_loop = asyncio.new_event_loop()
        threading.Thread(target=_tool_loop.run_forever, name="mcp-tool-loop", daemon=True).start()
    return _tool_loop


def _run_on_tool_loop(coro: Any) -> Any:
    """在常驻 tool loop 上同步执行协程并返回结果（调用方线程即使有自己的事件循环也可以，会阻塞等待）。"""
    return asyncio.run_coroutine_threadsafe(coro, _get_tool_loop()).result()


# 外部 server 的长连接：name -> 已连接的 Client（stdio 子进程随连接常驻，避免每次调用都拉起进程）
_external_clients: dict[str, Client] = {}
# 工具名 -> 所属外部 server 名；不在表里的工具走内存 server
_external_tool_owner: dict[str, str] = {}
_default_chat_tools: list[dict[str, Any]] | None = None


def _to_openai_tool(tool: Any) -> dict[str, Any]:
    # MCP SDK v2 uses snake_case; only access the old alias for v1 tools.
    try:
        input_schema = tool.input_schema
    except AttributeError:
        input_schema = tool.inputSchema
    return {
        "type": "function",
        "function": {
            "name": tool.name,
            "description": " ".join((tool.description or "").split()),
            "parameters": input_schema,
            "strict": False,
        },
    }


def _is_internal_tool(tool: Any) -> bool:
    namespace = (tool.meta or {}).get("aichat_sdk")
    return isinstance(namespace, dict) and namespace.get("internal") is True


async def _connect_external(server: Any) -> Client | None:
    client = server.create_client()
    try:
        await asyncio.wait_for(client.__aenter__(), timeout=MCP_TOOL_TIMEOUT_SECONDS)
    except Exception as e:
        # 子进程通常还没来得及把 stderr 刷完，稍等一下再取，报错里能带上真正的原因
        await asyncio.sleep(0.2)
        tail = server.stderr_tail()
        # WARNING 只带 stderr 最后一行（通常就是异常信息），完整 traceback 降到 DEBUG
        last_line = next((line for line in reversed(tail.splitlines()) if line.strip()), "")
        detail = f" (stderr: {last_line})" if last_line else ""
        server.error = f"{type(e).__name__}: {e}{detail}"
        logger.warning(f"external MCP server '{server.name}' unavailable, skipped: {server.error}")
        if tail:
            logger.debug(f"--- {server.name} stderr (last lines) ---\n{tail}")
        return None
    server.error = ""
    return client


async def _collect_tools() -> list[dict[str, Any]]:
    tools: list[dict[str, Any]] = []
    seen: set[str] = set()
    _external_tool_owner.clear()

    async with Client(mcp) as client:
        for tool in await client.list_tools():
            seen.add(tool.name)
            if not _is_internal_tool(tool):
                tools.append(_to_openai_tool(tool))

    for server in get_external_mcp_servers():
        client = _external_clients.get(server.name) or await _connect_external(server)
        if client is None:
            continue
        _external_clients[server.name] = client
        try:
            remote_tools = await asyncio.wait_for(client.list_tools(), timeout=MCP_TOOL_TIMEOUT_SECONDS)
        except Exception as e:
            logger.warning(f"list_tools failed on external MCP server '{server.name}': {e}")
            continue
        remote_tools = [tool for tool in remote_tools if not _is_internal_tool(tool)]
        for tool in remote_tools:
            if tool.name in seen:
                logger.warning(
                    f"tool '{tool.name}' from MCP server '{server.name}' shadowed by an earlier tool, skipped"
                )
                continue
            seen.add(tool.name)
            _external_tool_owner[tool.name] = server.name
            tools.append(_to_openai_tool(tool))
        logger.info(f"external MCP server '{server.name}' provides {len(remote_tools)} tool(s)")
    return tools


def add_mcp_server(name: str, command: str | None = None, args: list[str] | None = None, **kwargs: Any) -> None:
    """注册一个外部 MCP server（参数见 external.add_mcp_server），并让工具列表在下次取用时重建。"""
    _external.add_mcp_server(name, command, args, **kwargs)
    _invalidate_tools()


def load_mcp_servers(config: dict[str, Any]) -> None:
    """注册一批外部 MCP server（`{"mcpServers": {...}}`），并让工具列表在下次取用时重建。"""
    _external.load_mcp_servers(config)
    _invalidate_tools()


def load_mcp_servers_config(path: Any) -> None:
    """从 JSON 文件注册外部 MCP server，并让工具列表在下次取用时重建。"""
    _external.load_mcp_servers_config(path)
    _invalidate_tools()


def remove_mcp_server(name: str) -> None:
    """注销一个外部 MCP server 并断开它的长连接（stdio 子进程随之退出），工具列表下次取用时重建。

    宿主改配置时用：`load_mcp_servers` 只做合并注册，删掉或改过的 server 不显式注销的话，
    会一直留在注册表和 `_external_clients` 里继续供工具。没动过的 server 不要碰，
    它们的连接和子进程留着复用，重建 agent 时 `_collect_tools` 直接拿现成的 client。
    """
    _external.remove_mcp_server(name)
    client = _external_clients.pop(name, None)
    if client is not None:
        _run_on_tool_loop(_close_client(name, client))
    _invalidate_tools()


def register_default_tools_server(disabled_tools: list[str] | None = None) -> None:
    """注册 SDK 自带聊天工具的 stdio server（import 时已默认注册；被 remove 掉之后可用它重新接入）。

    disabled_tools 里的工具经 --disable 参数传给子进程，不对模型提供。开关变化时要先
    remove_mcp_server(DEFAULT_TOOLS_SERVER) 再注册，不然复用的旧连接供的还是旧工具集。
    """
    args = ["-m", "aichat_sdk.mcp_tool"]
    if disabled_tools:
        args += ["--disable", ",".join(disabled_tools)]
    add_mcp_server(DEFAULT_TOOLS_SERVER, sys.executable, args)


def get_builtin_tools() -> list[dict[str, str]]:
    """内存 FastMCP server 自己提供的工具（含描述），即工具列表里不属于任何外部 server 的那些。"""
    # 和 get_mcp_server_status 不同：内置工具跟有没有连过外部 server 无关，没构建过就现建
    tools = get_default_chat_tools()
    return sorted(
        (
            {"name": tool["function"]["name"], "description": tool["function"]["description"]}
            for tool in tools
            if tool["function"]["name"] not in _external_tool_owner
        ),
        key=lambda tool: tool["name"],
    )


def get_mcp_server_status() -> list[dict[str, Any]]:
    """每个外部 MCP server 的连接结果和它提供的工具（含描述），按上次构建工具列表时的情况。"""
    # 直接读缓存，不触发重建：没构建过工具列表时本来就没有状态可言
    descriptions = {tool["function"]["name"]: tool["function"]["description"] for tool in (_default_chat_tools or [])}
    tools_by_server: dict[str, list[dict[str, str]]] = {}
    for tool_name, owner in _external_tool_owner.items():
        tools_by_server.setdefault(owner, []).append(
            {"name": tool_name, "description": descriptions.get(tool_name, "")}
        )
    return [
        {
            "name": server.name,
            "connected": server.name in _external_clients,
            "error": server.error,
            "tools": sorted(tools_by_server.get(server.name, []), key=lambda tool: tool["name"]),
        }
        for server in get_external_mcp_servers()
    ]


def _invalidate_tools() -> None:
    global _default_chat_tools
    _default_chat_tools = None


def get_default_chat_tools() -> list[dict[str, Any]]:
    """把内存 FastMCP server 和外部 MCP server 的工具 schema 转成 OpenAI function calling 格式，首次调用时构建并缓存。"""
    global _default_chat_tools
    if _default_chat_tools is None:
        _default_chat_tools = _run_on_tool_loop(_collect_tools())
    return _default_chat_tools


async def _close_client(name: str, client: Client) -> None:
    try:
        await asyncio.wait_for(client.__aexit__(None, None, None), timeout=3)
    except Exception as e:
        logger.debug(f"closing external MCP server '{name}' failed: {e}")


async def _close_external_clients() -> None:
    for name, client in list(_external_clients.items()):
        await _close_client(name, client)
    _external_clients.clear()


def _shutdown_external_clients() -> None:
    """进程退出时尽量优雅关掉外部 stdio 子进程（daemon 线程不会自己收尾）。"""
    if _tool_loop is None or not _external_clients:
        return
    try:
        asyncio.run_coroutine_threadsafe(_close_external_clients(), _tool_loop).result(timeout=5)
    except Exception:
        pass


atexit.register(_shutdown_external_clients)


async def _call_tool(name: str, args: dict[str, Any]) -> str:
    owner = _external_tool_owner.get(name)
    if owner is None:
        async with Client(mcp) as client:
            result = await client.call_tool(name, args)
    else:
        result = await _external_clients[owner].call_tool(name, args)
    return "\n".join(block.text for block in result.content if getattr(block, "text", None))


async def stream_mcp_tool(name: str, args: dict[str, Any]) -> AsyncIterator[dict[str, Any]]:
    """从 mcp_tool 的 MCP 注册表取得流式工具并逐项返回其原始结果。

    流式工具不走标准 MCP CallTool 序列化；标准调用会把异步生成器转成文本，
    无法逐包传递音频。mcp_tool 除了作为 stdio 子进程供普通工具，其注册表也在
    宿主进程内 import 一份，流式工具由这里直调，并要求工具返回 AsyncIterator。
    """
    tool = await tools_mcp.get_tool(name)
    stream = tool.fn(**args)
    if not hasattr(stream, "__aiter__"):
        raise TypeError(f"MCP tool '{name}' is not a streaming tool")
    async for item in stream:
        yield item


async def dispatch_mcp_tool(name: str, arguments_json: str) -> tuple[str, float]:
    """分发工具调用到内存 FastMCP server 或对应的外部 MCP server，超时上限 MCP_TOOL_TIMEOUT_SECONDS 秒。"""
    try:
        args = json.loads(arguments_json) if arguments_json else {}
    except json.JSONDecodeError as e:
        return f"Error: invalid JSON arguments: {e}", 0.0
    start = time.perf_counter()
    future = asyncio.wrap_future(asyncio.run_coroutine_threadsafe(_call_tool(name, args), _get_tool_loop()))
    done, _ = await asyncio.wait({future}, timeout=MCP_TOOL_TIMEOUT_SECONDS)
    if future in done:
        try:
            text = future.result()
        except Exception as e:
            text = f"Error: {e}"
    else:
        # 超时后放弃等待：卡住的同步工具无法强杀，只能不再拖住主循环；
        # cancel 让还没开始跑的调用尽快清理，done_callback 取走异常避免告警
        future.cancel()
        future.add_done_callback(lambda f: f.cancelled() or f.exception())
        text = f"Error: tool '{name}' timed out after {MCP_TOOL_TIMEOUT_SECONDS}s"
    return text, time.perf_counter() - start


