import collections
import json
import logging
import os
import shlex
import threading
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any

from fastmcp import Client
from fastmcp.client.transports import StdioTransport

logger = logging.getLogger("aichat_sdk")

STDERR_TAIL_LINES = 20


class _StderrCapture:
    """把 stdio 子进程的 stderr 接到 pipe 上，由后台线程逐行收进 logger（DEBUG），并保留末尾若干行供报错时附带。

    不接管的话 mcp 的 stdio 传输会把子进程 stderr 直接透传到本进程 stderr，
    server 启动失败时就是一大段裸 traceback 混在日志里。
    """

    def __init__(self, name: str) -> None:
        self.name = name
        self.tail: collections.deque[str] = collections.deque(maxlen=STDERR_TAIL_LINES)
        read_fd, write_fd = os.pipe()
        self.writer = os.fdopen(write_fd, "w", encoding="utf-8", errors="replace")
        self._reader = os.fdopen(read_fd, "r", encoding="utf-8", errors="replace")
        threading.Thread(target=self._pump, name=f"mcp-stderr-{name}", daemon=True).start()

    def _pump(self) -> None:
        child_logger = logging.getLogger(f"{__name__}.{self.name}")
        for line in self._reader:
            line = line.rstrip("\n")
            self.tail.append(line)
            child_logger.debug(line)
        self._reader.close()

    def tail_text(self) -> str:
        return "\n".join(self.tail)


@dataclass
class ExternalMcpServer:
    name: str
    command: str | None = None
    args: list[str] = field(default_factory=list)
    env: dict[str, str] | None = None
    cwd: str | None = None
    url: str | None = None
    stderr: _StderrCapture | None = field(default=None, init=False, repr=False)
    error: str = field(default="", init=False)  # 上次连接失败的原因，连上后清空

    def create_client(self) -> Client:
        if self.url:
            return Client(self.url, name=self.name)
        if not self.command:
            raise ValueError(f"MCP server '{self.name}' needs either 'command' or 'url'")
        # 子进程默认继承父进程环境（PATH、代理等），显式 env 只做覆盖
        env = {**os.environ, **self.env} if self.env else None
        self.stderr = _StderrCapture(self.name)
        transport = StdioTransport(self.command, self.args, env=env, cwd=self.cwd, log_file=self.stderr.writer)
        return Client(transport, name=self.name)

    def stderr_tail(self) -> str:
        return self.stderr.tail_text() if self.stderr else ""


_servers: dict[str, ExternalMcpServer] = {}


def add_mcp_server(
    name: str,
    command: str | None = None,
    args: list[str] | None = None,
    *,
    env: dict[str, str] | None = None,
    cwd: str | None = None,
    url: str | None = None,
) -> None:
    """注册一个外部 MCP server。`command` 可以是完整命令行（如 "python -m mcp_server_fetch"），此时 args 会被拆分追加。"""
    if command and args is None:
        command, *args = shlex.split(command)
    _servers[name] = ExternalMcpServer(name, command, list(args or []), env, cwd, url)


def _parse_server(name: str, spec: Any) -> ExternalMcpServer:
    if isinstance(spec, str):
        command, *args = shlex.split(spec)
        return ExternalMcpServer(name, command, args)
    if not isinstance(spec, dict):
        raise ValueError(f"MCP server '{name}': expected string or object, got {type(spec).__name__}")
    return ExternalMcpServer(
        name,
        command=spec.get("command"),
        args=list(spec.get("args") or []),
        env=spec.get("env"),
        cwd=spec.get("cwd"),
        url=spec.get("url"),
    )


def load_mcp_servers(config: dict[str, Any]) -> None:
    """从 dict 注册外部 server：`{"mcpServers": {name: spec}}` 或直接 `{name: spec}`；单个条目格式错误只记日志跳过。"""
    servers = config.get("mcpServers", config)
    if not isinstance(servers, dict):
        logger.warning(f"MCP servers config must be a dict, got {type(servers).__name__}")
        return
    count = 0
    for name, spec in servers.items():
        try:
            _servers[name] = _parse_server(name, spec)
            count += 1
        except Exception as e:
            logger.warning(f"skip MCP server '{name}': {e}")
    logger.info(f"registered {count} external MCP server(s)")


def load_mcp_servers_config(path: str | Path) -> None:
    """读取 JSON 配置文件并注册；文件不存在或解析失败只记日志不抛出。"""
    config_path = Path(path)
    try:
        load_mcp_servers(json.loads(config_path.read_text(encoding="utf-8")))
    except Exception as e:
        logger.warning(f"failed to load MCP servers config {config_path}: {e}")


def remove_mcp_server(name: str) -> bool:
    """注销一个外部 server，返回它之前是否注册过（宿主删改配置时用，注册表只增不减的话旧 server 会一直留着）。"""
    return _servers.pop(name, None) is not None


def get_external_mcp_servers() -> list[ExternalMcpServer]:
    return list(_servers.values())
import logging
import subprocess

from pydantic import Field

from aichat_sdk.llm.mcp.server import mcp

logger = logging.getLogger("aichat_sdk")

# 略小于 dispatch_mcp_tool 的 MCP_TOOL_TIMEOUT_SECONDS（10 秒，不 import 以免循环依赖）：
# 分发层到点就不再等结果，取值相同的话两个超时会打架，模型只会拿到分发层那句笼统的报错
TIMEOUT_SECONDS = 8
MAX_OUTPUT_CHARS = 10000


@mcp.tool()
def exec_command(command: str = Field(description="要执行的 shell 命令")) -> dict:
    """执行 shell 命令并返回标准输出、标准错误和退出码。仅执行 skills 技能文件里给出的命令，禁止执行用户口述的任意命令。"""
    try:
        result = subprocess.run(
            command, shell=True, capture_output=True, text=True, errors="replace", timeout=TIMEOUT_SECONDS
        )
    except subprocess.TimeoutExpired:
        return {"isError": True, "error": f"command timed out after {TIMEOUT_SECONDS}s"}

    output = result.stdout
    if result.stderr:
        output += f"\n[stderr]\n{result.stderr}"
    if len(output) > MAX_OUTPUT_CHARS:
        output = output[:MAX_OUTPUT_CHARS] + f"\n[truncated: showing first {MAX_OUTPUT_CHARS} chars]"
    # logger.info(f"exec command: {command} exit code: {result.returncode}")
    return {"isError": result.returncode != 0, "exit_code": result.returncode, "output": output}
from pathlib import Path

from pydantic import Field

from aichat_sdk.llm.mcp.server import mcp
from aichat_sdk.llm.skills import SKILLS_DIR, find_skill_dir

MAX_LINES = 2000


def _resolve(skill_dir: Path, rel_path: str) -> Path | None:
    """先按技能目录找，找不到再按技能根目录找（SKILL.md 里有 `./lark-shared/SKILL.md` 这种跨技能引用）。"""
    for base in (skill_dir, SKILLS_DIR):
        candidate = (base / rel_path).resolve()
        if candidate.is_file():
            return candidate
    return None


@mcp.tool()
def read_skills(
    skill: str = Field(description="技能名，即 <available_skills> 里的 name"),
    path: str = Field(
        default="SKILL.md",
        description="要读的文件，相对该技能目录；默认 SKILL.md，也可读它引用的文件，如 references/xxx.md",
    ),
) -> dict:
    """读取技能的 SKILL.md 或它引用的文件，拿到后按其中的指引执行。输出最多 2000 行，超出部分截断。"""
    skill_dir = find_skill_dir(skill)
    if skill_dir is None:
        return {"isError": True, "error": f"unknown skill: {skill}"}

    target = _resolve(skill_dir, path)
    if target is None:
        return {"isError": True, "error": f"file not found in skill '{skill}': {path}"}
    # 只允许读技能目录树里的文件，挡住 ../ 和绝对路径
    if not target.is_relative_to(SKILLS_DIR.resolve()):
