400	// ---------------- 外部 MCP servers ----------------

400	// ---------------- 外部 MCP servers ----------------
401	
402	function splitCommand(line) {  // 够用的 shlex：按空白切，引号里的空格不切
403	  const parts = [];
404	  let cur = "", quote = null, started = false;
405	  for (const ch of line.trim()) {
406	    if (quote) { if (ch === quote) quote = null; else cur += ch; }
407	    else if (ch === '"' || ch === "'") { quote = ch; started = true; }
408	    else if (/\s/.test(ch)) { if (cur || started) { parts.push(cur); cur = ""; started = false; } }
409	    else cur += ch;
410	  }
411	  if (cur || started) parts.push(cur);
412	  return parts;
413	}
414	
415	function joinCommand(parts) {
416	  return parts.filter(Boolean).map((p) => (/\s/.test(p) ? JSON.stringify(p) : p)).join(" ");
417	}
418	
419	function specToTarget(spec) {
420	  if (typeof spec === "string") return spec;      // SDK 支持直接写命令行字符串
421	  if (!spec || typeof spec !== "object") return "";
422	  if (spec.url) return spec.url;
423	  return joinCommand([spec.command || "", ...(spec.args || [])]);
424	}
425	
426	function targetToSpec(target) {
427	  if (/^https?:\/\//i.test(target)) return { url: target };
428	  const [command = "", ...args] = splitCommand(target);
429	  return { command, args };
430	}
431	
432	function mcpExtras(spec) {  // env / cwd 这些页面上不编辑的字段原样留着，只能在 JSON 模式改
433	  const extras = {};
434	  if (spec && typeof spec === "object") {
435	    for (const [key, value] of Object.entries(spec)) {
436	      if (!["command", "args", "url", "enabled"].includes(key)) extras[key] = value;
437	    }
438	  }
439	  return extras;
440	}
441	
442	function addMcpRow(name, spec, open) {
443	  const row = el("div", "mcp-row");
444	  row.dataset.extras = JSON.stringify(mcpExtras(spec));
445	
446	  // 摘要行：勾选启用、展开箭头、名称、类型、状态
447	  const enabled = el("input");
448	  enabled.type = "checkbox";
449	  enabled.className = "mcp-enabled";
450	  enabled.title = "启用";
451	  enabled.checked = !(spec && typeof spec === "object" && spec.enabled === false);
452	
453	  const arrow = el("span", "mcp-arrow", "▶");
454	  const nameInput = el("input", "mcp-name");
455	  nameInput.value = name || "";
456	  nameInput.placeholder = "名称";
457	  const type = el("span", "mcp-type");
458	  const summary = el("div", "mcp-summary");
459	  summary.append(enabled, arrow, nameInput, type, el("span", "mcp-state"));
460	
461	  // 详情：命令行、工具列表、失败原因、删除
462	  const target = el("textarea", "mcp-target");
463	  target.rows = 1;
464	  target.spellcheck = false;
465	  target.value = specToTarget(spec);
466	  target.placeholder = "python -m mcp_server_fetch 或 http://127.0.0.1:8000/mcp";
467	  const del = el("button", "mcp-del", "✕ 删除");
468	  del.type = "button";
469	  const install = el("button", "mcp-install");  // 缺 pip 包连不上时才显示，renderMcpStatus 管
470	  install.type = "button";
471	  install.hidden = true;
472	  install.addEventListener("click", () => installMcp(row, install));
473	  const body = el("div", "mcp-body");
474	  body.append(target, el("div", "mcp-tools"), el("div", "mcp-error"), install, del);
475	
476	  const syncType = () => (type.textContent = /^https?:\/\//i.test(target.value.trim()) ? "http" : "stdio");
477	  const syncOff = () => row.classList.toggle("off", !enabled.checked);
478	  target.addEventListener("input", () => {
479	    syncType();
480	    setMcpRowOpen(row, true);  // 顺带按新内容重新撑高
481	  });
482	  enabled.addEventListener("change", syncOff);
483	  del.addEventListener("click", () => {
484	    row.remove();
485	    updateMcpCount();
486	  });
487	  summary.addEventListener("click", (event) => {  // 点摘要行展开/收起，点勾选框和名称除外
488	    if (event.target !== enabled && event.target !== nameInput) {
489	      setMcpRowOpen(row, !row.classList.contains("open"));
490	    }
491	  });
492	  syncType();
493	  syncOff();
494	
495	  row.append(summary, body);
496	  $("#mcp-rows").append(row);
497	  setMcpRowOpen(row, !!open);
498	  return row;
499	}
500	
501	function setMcpRowOpen(row, open) {
502	  row.classList.toggle("open", open);
503	  const target = row.querySelector(".mcp-target");
504	  if (!open || !target) return;  // 只读行只有工具列表，没有命令行
505	  target.style.height = "auto";  // 收起状态 display:none 量不到高度，只在展开时算
506	  const border = target.offsetHeight - target.clientHeight;  // border-box：height 得把上下边框算进去
507	  target.style.height = target.scrollHeight + border + "px";
508	}
509	
510	function renderMcpRows(mcp) {
511	  $("#mcp-rows").replaceChildren();
512	  for (const [name, spec] of Object.entries((mcp && mcp.mcpServers) || {})) addMcpRow(name, spec, false);
513	  updateMcpCount();
514	}
515	
516	function updateMcpCount() {
517	  const external = document.querySelectorAll("#mcp-defaults .mcp-row, #mcp-rows .mcp-row").length;
518	  $("#mcp-count").textContent = " · " + external;
519	  $("#mcp-empty").hidden = external > 0;
520	}
521	
522	function collectMcp() {
523	  if (jsonMode) return $("#mcp-json").value;  // 原样交给服务端解析，报错信息统一
524	  const servers = {};
525	  for (const row of document.querySelectorAll("#mcp-rows .mcp-row")) {
526	    const name = row.querySelector(".mcp-name").value.trim();
527	    const target = row.querySelector(".mcp-target").value.trim();
528	    if (!name && !target) continue;  // 整行空着的当没填
529	    const spec = { ...JSON.parse(row.dataset.extras), ...targetToSpec(target) };
530	    if (!row.querySelector(".mcp-enabled").checked) spec.enabled = false;
531	    servers[name] = spec;
532	  }
533	  return { mcpServers: servers };
534	}
535	
536	function renderMcpStatus(list) {
537	  renderDefaultMcpRows(list.filter((item) => item.readonly));
538	  const byName = Object.fromEntries(list.filter((item) => !item.readonly).map((item) => [item.name, item]));
539	  for (const row of document.querySelectorAll("#mcp-rows .mcp-row")) {
540	    const state = byName[row.querySelector(".mcp-name").value.trim()];
541	    const badge = row.querySelector(".mcp-state");
542	    const error = row.querySelector(".mcp-error");
543	    badge.className = "mcp-state";
544	    badge.removeAttribute("title");
545	    error.textContent = "";
546	    if (!row.querySelector(".mcp-enabled").checked) {
547	      badge.textContent = "已停用";
548	    } else if (!state) {
549	      badge.textContent = "保存后生效";
550	    } else if (state.error) {
551	      badge.textContent = "连接失败";
552	      badge.classList.add("err");
553	      error.textContent = state.error;
554	    } else if (state.connected) {
555	      badge.textContent = state.tools.length ? state.tools.length + " 个工具" : "已连接";
556	      badge.classList.add("ok");
557	    } else {
558	      badge.textContent = "未连接";
559	    }
560	    // 缺 pip 包连不上的给一键安装按钮；点击后到装完的过程中不碰它（dataset.busy），别把「安装中…」刷掉
561	    const install = row.querySelector(".mcp-install");
562	    const installable = state && state.install && row.querySelector(".mcp-enabled").checked;
563	    if (!install.dataset.busy) {
564	      install.hidden = !installable;
565	      if (installable) {
566	        install.disabled = !!state.installing;
567	        install.textContent = state.installing ? "安装中…" : "⬇ pip install " + state.install;
568	      }
569	    }
570	    renderToolList(row, (state && state.tools) || []);
571	    if (state && state.error && row.dataset.errorSeen !== state.error) {
572	      row.dataset.errorSeen = state.error;  // 同一个错误只自动展开一次，收起来了就别再弹开
573	      row.closest(".group").classList.add("open");  // 分区默认收着，得先弹开分区才量得到高度，也才看得见
574	      setMcpRowOpen(row, true);
575	    }
576	  }
577	}
578	
579	async function installMcp(row, btn) {
580	  const name = row.querySelector(".mcp-name").value.trim();
581	  btn.dataset.busy = "1";
582	  btn.disabled = true;
583	  btn.textContent = "安装中…（装完会自动重启重连）";
584	  try {
585	    const res = await fetch("/api/mcp/install", {
586	      method: "POST",
587	      headers: { "Content-Type": "application/json" },
588	      body: JSON.stringify({ name }),
589	    });
590	    const data = await res.json();
591	    setNote(data.ok ? "已安装 " + data.package + "，ChatBot 已重启重连" : (data.error || "安装失败"), data.ok);
592	  } catch (e) {
593	    setNote(String(e), false);
594	  } finally {
595	    delete btn.dataset.busy;
596	    btn.disabled = false;
597	    loadState();  // 装完 MCP 包会重启重连，按最新状态重画按钮和徽章
598	  }
599	}
600	
