775	async function installSkill(mode) {
776	  if (skillInstalling || skillCommandRunning) return;
777	  let url, options;
778	  if (mode === "upload") {
779	    const file = $("#skill-file").files[0];
780	    const error = skillFileError(file);
781	    if (error) return skillInstallNote(error, false);
782	    url = "/api/skills/install?filename=" + encodeURIComponent(file.name);
783	    options = {method: "POST", headers: {"Content-Type": "application/octet-stream"}, body: file};
784	  } else {
785	    const command = $("#skill-command").value.trim();
786	    if (!command) return skillInstallNote("请输入安装命令", false);
787	    url = "/api/skills/command";
788	    options = {method: "POST", headers: {"Content-Type": "application/json"}, body: JSON.stringify({command})};
789	  }
790	  skillInstalling = true;
791	  setSkillInstallMode(mode);
792	  skillInstallResults[mode] = "idle";
793	  skillInstallButtons();
794	  $("#skill-install-output").hidden = true;
795	  $("#skill-install-output").textContent = "";
796	  skillInstallNote(mode === "upload" ? "上传安装中…" : "命令安装中…", true);
797	  try {
798	    const res = await fetch(url, options);
799	    const data = await res.json();
800	    if (data.output) {
801	      $("#skill-install-output").textContent = data.output;
802	      $("#skill-install-output").hidden = false;
803	    }
804	    if (!res.ok || !data.ok) throw new Error(data.error || "安装失败");
805	    // 安装只刷新技能清单，保留用户尚未保存的表单和技能开关。
806	    const toggles = collectSkills();
807	    renderSkills(data.skills || [], data.skills_dir);
808	    for (const box of document.querySelectorAll("#skill-rows .mcp-enabled")) {
809	      if (Object.hasOwn(toggles, box.dataset.skill)) {
810	        box.checked = toggles[box.dataset.skill];
811	        box.dispatchEvent(new Event("change"));
812	      }
813	    }
814	    $("#skill-search").value = "";
815	    filterSkills();
816	    if (mode === "upload") {
817	      $("#skill-file").value = "";
818	      updateSkillFile();
819	    }
820	    const names = data.skill ? [data.skill.name] : data.installed;
821	    skillInstallResults[mode] = names?.length ? "success" : "completed";
822	    skillInstallNote(names?.length ? "已安装 " + names.join("、") + "，保存并重启后生效" : "命令执行完成，未发现新增技能。请查看输出，并确认安装到了 " + data.skills_dir, true);
823	  } catch (e) {
824	    skillInstallResults[mode] = "error";
825	    skillInstallNote(e.message || String(e), false);
826	  } finally {
827	    skillInstalling = false;
828	    skillCommandRunning = false;
829	    skillInstallButtons();
830	  }
831	}
