1021	function formatUsage(u) {  // assistant 消息上的 token 用量：↑prompt(缓存命中) ↓completion · 首包耗时
1022	  const prompt = u.prompt_tokens || 0;
1023	  const details = u.prompt_tokens_details || {};
1024	  const cached = details.cached_tokens || u.prompt_cache_hit_tokens || 0;
1025	  const hit = prompt && cached ? "（缓存 " + Math.round(cached / prompt * 100) + "%）" : "";
1026	  const ttft = u.first_chunk_latency_ms ? " · 首包 " + u.first_chunk_latency_ms + "ms" : "";
1027	  return "↑" + prompt + hit + " ↓" + (u.completion_tokens || 0) + ttft;
1028	}
