// ---------------- 定时任务 ----------------
// 任务存在 harness 数据库，到点由 harness 执行；改动立即生效，不走「保存并重启」。
// 列表在页面加载、操作之后，以及 SSE 推来新的 revision（语音新建、到点执行等）时重取。
const WEEKDAY_LABELS = ["一", "二", "三", "四", "五", "六", "日"];
let scheduleTasks = [];
let scheduleRevision = null;
let scheduleToday = "";      // 配置时区的今天，新建不重复的任务时做默认日期
let scheduleEditing = null;  // 正在编辑的任务；null 是新建
let scheduleSaving = false;

function scheduleNote(text, ok) {
  $("#schedule-note").textContent = text;
  $("#schedule-note").className = "note " + (ok ? "ok" : "err");
}

async function scheduleApi(method, url, body) {
  const options = { method };
  if (body !== undefined) {
    options.headers = { "Content-Type": "application/json" };
    options.body = JSON.stringify(body);
  }
  const res = await fetch(url, options);
  const data = await res.json().catch(() => ({}));
  if (!res.ok || !data.ok) throw new Error(data.error || "HTTP " + res.status);
  return data;
}

async function loadSchedules() {
  try {
    const data = await scheduleApi("GET", "/api/schedules");
    scheduleTasks = data.tasks || [];
    scheduleToday = data.today || "";
    $("#schedule-tz").textContent = data.timezone || "";
    renderSchedules();
  } catch (e) {
    scheduleNote("加载定时任务失败：" + (e.message || e), false);
  }
}

function renderScheduleState(state) {  // SSE 推来的调度状态：revision 变了就重取列表
  $("#schedule-error").textContent = state.error || "";
  if (state.revision === scheduleRevision) return;
  scheduleRevision = state.revision;
  loadSchedules();
}

function scheduleName(task) {
  return task.title || task.prompt.split("\n")[0];
}

function renderSchedules() {
  const tasks = scheduleTasks;
  const enabled = tasks.filter((task) => task.enabled).length;
  $("#schedule-count").textContent = " · " + (enabled === tasks.length ? tasks.length : enabled + "/" + tasks.length);
  const open = new Set([...document.querySelectorAll("#schedule-rows .mcp-row.open")].map((row) => row.dataset.id));
  $("#schedule-rows").replaceChildren(...tasks.map((task) => renderScheduleRow(task, open.has(String(task.id)))));
  $("#schedule-empty").hidden = tasks.length > 0;
}

function renderScheduleRow(task, open) {
  const row = el("div", "mcp-row" + (task.enabled ? "" : " off") + (open ? " open" : ""));
  row.dataset.id = task.id;
  const enabled = el("input");
  enabled.type = "checkbox";
  enabled.checked = task.enabled;
  enabled.title = task.enabled ? "暂停" : "启用";
  enabled.setAttribute("aria-label", (task.enabled ? "暂停：" : "启用：") + scheduleName(task));
  enabled.addEventListener("change", () => toggleSchedule(task, enabled));
  const name = el("span", "schedule-name", scheduleName(task));
  name.title = task.prompt;
  // 摘要行：还会执行的显示排期，执行完、暂停、错过的显示状态
  const failed = task.enabled && (task.last_status === "error" || task.status_text === "已错过");
  const state = el("span", "mcp-state" + (failed ? " err" : ""), task.enabled && task.next_run ? task.summary : task.status_text);
  state.title = task.status_text;
  const summary = el("div", "mcp-summary");
  summary.append(enabled, el("span", "mcp-arrow", "▶"), name, state);
  summary.addEventListener("click", (event) => {  // 点摘要行展开/收起，点勾选框除外
    if (event.target !== enabled) row.classList.toggle("open");
  });

  const meta = el("div", "schedule-meta");
  meta.append(el("div", null, task.summary + " · " + task.status_text));
  if (task.last_run_text) {
    const result = { done: "已执行", missed: "已错过", error: "执行失败" }[task.last_status] || "";
    meta.append(el("div", null, "上次 " + task.last_run_text + (result ? " · " + result : "")));
  }
  if (task.last_status === "error" && task.last_error) meta.append(el("div", "err", task.last_error));
  const ops = el("div", "schedule-ops");
  for (const [text, handler, cls] of [
    ["立即运行", () => runSchedule(task)],
    ["编辑", () => openScheduleDialog(task)],
    ["删除", () => deleteSchedule(task), "danger"],
  ]) {
    const button = el("button", cls, text);
    button.type = "button";
    button.addEventListener("click", handler);
    ops.append(button);
  }
  const body = el("div", "mcp-body");
  body.append(el("div", "schedule-prompt", task.prompt), meta, ops);
  row.append(summary, body);
  return row;
}

async function toggleSchedule(task, box) {
  box.disabled = true;
  try {
    await scheduleApi("PATCH", "/api/schedules/" + task.id, { enabled: box.checked });
    scheduleNote((box.checked ? "已启用：" : "已暂停：") + scheduleName(task), true);
  } catch (e) {
    box.checked = !box.checked;
    scheduleNote(e.message || String(e), false);
  } finally {
    box.disabled = false;
    loadSchedules();
  }
}

async function runSchedule(task) {
  try {
    await scheduleApi("POST", "/api/schedules/" + task.id + "/run");
    scheduleNote("已触发「" + scheduleName(task) + "」，正在对话的话会等这一轮说完", true);
  } catch (e) {
    scheduleNote(e.message || String(e), false);
  }
}

async function deleteSchedule(task) {
  if (!confirm("删除定时任务「" + scheduleName(task) + "」？")) return;
  try {
    await scheduleApi("DELETE", "/api/schedules/" + task.id);
    scheduleNote("已删除：" + scheduleName(task), true);
  } catch (e) {
    scheduleNote(e.message || String(e), false);
  }
  loadSchedules();
}

function selectedWeekdays() {
  return [...document.querySelectorAll("#schedule-weekdays button")]
    .filter((button) => button.getAttribute("aria-pressed") === "true")
    .map((button) => Number(button.dataset.day));
}

function setWeekdays(days) {
  for (const button of document.querySelectorAll("#schedule-weekdays button")) {
    button.setAttribute("aria-pressed", String(days.includes(Number(button.dataset.day))));
  }
}

function todayWeekday() {  // 配置时区的今天是星期几：1=周一 … 7=周日
  const day = (scheduleToday ? new Date(scheduleToday + "T00:00:00") : new Date()).getDay();
  return day === 0 ? 7 : day;
}

function setScheduleAdvanced(open) {
  $("#schedule-advanced-body").hidden = !open;
  $("#schedule-advanced").setAttribute("aria-expanded", String(open));
}

function syncScheduleForm() {  // 按重复方式切换日期、星期、时间、分钟几行，并决定能不能提交
  const repeat = $("#schedule-repeat").value;
  $("#schedule-date-row").hidden = repeat !== "once";
  $("#schedule-weekdays-row").hidden = repeat !== "weekly";
  $("#schedule-time-row").hidden = repeat === "hourly";
  $("#schedule-minute-row").hidden = repeat !== "hourly";
  if (repeat === "weekly" && !selectedWeekdays().length) setWeekdays([todayWeekday()]);
  if (repeat === "once" && !$("#schedule-date").value) $("#schedule-date").value = scheduleToday;
  const minute = $("#schedule-minute").value.trim();
  const ready = $("#schedule-prompt").value.trim()
    && (repeat === "hourly" ? /^\d{1,2}$/.test(minute) && Number(minute) <= 59 : $("#schedule-time").value)
    && (repeat !== "once" || $("#schedule-date").value)
    && (repeat !== "weekly" || selectedWeekdays().length);
  $("#schedule-submit").disabled = scheduleSaving || !ready;
}

function openScheduleDialog(task = null) {
  scheduleEditing = task;
  const repeat = task ? task.repeat : "daily";
  const time = task && repeat !== "hourly" ? task.time : "09:00";
  $("#schedule-title").textContent = task ? "编辑定时任务" : "设置定时任务";
  $("#schedule-submit").textContent = task ? "保存" : "创建";
  $("#schedule-prompt").value = task ? task.prompt : "";
  $("#schedule-repeat").value = repeat;
  $("#schedule-time").step = time.length > 5 ? "1" : "60";  // 语音设的「几分钟后」带秒
  $("#schedule-time").value = time;
  $("#schedule-minute").value = task && repeat === "hourly" ? String(Number(task.time.slice(3, 5))) : "0";
  $("#schedule-date").value = task && task.date ? task.date : scheduleToday;
  setWeekdays(task ? task.weekdays : []);
  $("#schedule-name").value = task ? task.title : "";
  setScheduleAdvanced(Boolean(task && task.title));
  $("#schedule-dialog-note").textContent = "";
  syncScheduleForm();
  $("#schedule-dialog").showModal();
  $("#schedule-prompt").focus();
}

function scheduleFormValues() {
  const repeat = $("#schedule-repeat").value;
  const values = { prompt: $("#schedule-prompt").value.trim(), title: $("#schedule-name").value.trim(), repeat };
  values.time = repeat === "hourly"
    ? "00:" + String(Number($("#schedule-minute").value)).padStart(2, "0")
    : $("#schedule-time").value;
  if (repeat === "once") values.date = $("#schedule-date").value;
  if (repeat === "weekly") values.weekdays = selectedWeekdays();
  const old = scheduleEditing;
  // 编辑时时间没动就不提交时间字段：只改说明或名称的话，已经执行过的一次性任务也能保存
  if (old && repeat === old.repeat && values.time === old.time
      && (repeat !== "once" || values.date === old.date)
      && (repeat !== "weekly" || values.weekdays.join() === old.weekdays.join())) {
    for (const key of ["repeat", "time", "date", "weekdays"]) delete values[key];
  }
  return values;
}

async function submitSchedule(event) {
  event.preventDefault();
  if (scheduleSaving || $("#schedule-submit").disabled) return;
  const editing = scheduleEditing;
  scheduleSaving = true;
  syncScheduleForm();
  $("#schedule-dialog-note").textContent = "";
  try {
    const values = scheduleFormValues();
    const data = editing
      ? await scheduleApi("PATCH", "/api/schedules/" + editing.id, values)
      : await scheduleApi("POST", "/api/schedules", values);
    $("#schedule-dialog").close();
    $("#schedule-group").classList.add("open");
    scheduleNote((editing ? "已保存：" : "已创建：") + scheduleName(data.task) + " · " + data.task.status_text, true);
    loadSchedules();
  } catch (e) {
    $("#schedule-dialog-note").textContent = e.message || String(e);
  } finally {
    scheduleSaving = false;
    syncScheduleForm();
  }
}

$("#schedule-weekdays").replaceChildren(...WEEKDAY_LABELS.map((label, index) => {
  const button = el("button", null, label);
  button.type = "button";
  button.dataset.day = index + 1;
  button.setAttribute("aria-pressed", "false");
  button.setAttribute("aria-label", "周" + label);
  button.addEventListener("click", () => {
    button.setAttribute("aria-pressed", String(button.getAttribute("aria-pressed") !== "true"));
    syncScheduleForm();
  });
  return button;
}));
$("#schedule-add").addEventListener("click", () => openScheduleDialog());
